head.script:
scwin.gVar = {
    "cID" : ""
}



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[secret > P > id]<br/>Secret 컴포넌트의 ID 를 설정합니다.",
    "validation" : [
        "동일 Scope 에서 Secret 컴포넌트를 구별할 수 있는 유일값을 설정합니다.",
        "값을 설정하지 않으면 화면 렌더링 과정에서 임의의 ID 값이 설정됩니다.",
        "스크립트에서 해당 컴포넌트에 접근하려면 ID 값을 반드시 설정하여야 합니다.",
        "화면 렌더링 과정에서 config.xml 에 설정된 Scope Variable 값이 ID 에 자동으로 추가됩니다.",
        "스크립트에서는 Scope Variable 이 추가된 ID 가 아닌 원래 설정된 ID 를 사용해야 합니다.",
        "WFrame 환경에서는 렌더링 과정에서 ID 가 변경되므로 CSS 정의 시 id Selector 대신 class Selector 를 사용하여야 합니다.",
        "속성명이나 메소드명과 같은 예약어를 설정할 경우 오류가 발생할 수 있습니다.",
    ]
}



// 공통 판(common_P_id_1) 의 validation 2건으로는 secret 가이드의 @spec 내용을 덮지 못해 tData 를 덮어쓴다
scwin.wf_sample_onwframeload = function () {
    let wf_body_left = wf_sample.getObj("wf_body_left");
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.onpageload = function () {
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof label1 !== 'undefined') {
        label1.remove();
    }

    if (typeof scwin.target1 !== 'undefined') {
        scwin.target1.remove();
    }

    $c.gcm.createLabel('label="[전제] target1 은 Secret 컴포넌트(초기값 secret)이며 여러 WFrame 이 중첩된 화면 안에 생성됩니다\n[절차] 위 ID 입력창에 일반값(secret1) / 빈값 / 예약어(setValue) 를 각각 입력하고 Target 재생성 -> getID 버튼 클릭\n[확인] 결과창의 getID 값, 원래 설정 ID 로의 컴포넌트 조회 결과, id / class Selector 조회 개수"', '', 'label1');

    // 조건 설정
    let cID = scwin.gVar["cID"];

    // comp 생성
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strTarget += '<xf:secret ' + strNameSpace + ' class="secretClass" style="width:200px; height:40px;"></xf:secret>';

    scwin.target1 = await $p.dynamicCreate(
        cID,
        "secret",
        strTarget,
        grp_comp
    );

    // secret 은 initValue 속성이 없어 생성 후 setValue 로 초기값을 설정한다
    scwin.target1.setValue("secret");

    // validation 1, 2, 4 는 공통 판의 getID 버튼 출력으로 판정한다
    let objBottom = wf_sample.getObj("wf_body_bottom").getObj("scwin");

    // validation 3, 5, 7 판정 출력
    objBottom.setReturnValue("원래 설정 ID(" + (cID === "" ? "미설정" : cID) + ") 로 컴포넌트 조회 : " + ($p.getComponentById(cID) === scwin.target1));

    // validation 6 판정 출력 (ID 를 설정한 경우에만 id Selector 대비가 성립)
    if (cID !== "") {
        objBottom.setReturnValue("id Selector(#" + cID + ") 조회 개수 : " + document.querySelectorAll("[id='" + cID + "']").length + " / class Selector(.secretClass) 조회 개수 : " + document.querySelectorAll(".secretClass").length);
    }
}
